SELECT admin_user_id
FROM fair_admin_assignments
WHERE fair_id = #{fairId}

SELECT canceled_at AS canceledAt, status
FROM fairs
WHERE fair_id = #{fairId}

SELECT f.fair_id FROM fairs f JOIN recruit_notice rn ON rn.fair_id = f.fair_id WHERE f.fair_id IN
#{fairId}
AND rn.recruit_deadline > #{now} AND f.canceled_at IS NULL AND f.status != 'ENDED'
